import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"Translation Environment Install & Update","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/package-update.md","filePath":"en/guide/package-update.md"}`),a={name:`en/guide/package-update.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="translation-environment-install-update" tabindex="-1">Translation Environment Install &amp; Update <a class="header-anchor" href="#translation-environment-install-update" aria-label="Permalink to “Translation Environment Install &amp; Update”">​</a></h1><p>Since <strong>v4.1.0</strong>, Zotero PDF2zh keeps <strong>Server/plugin source updates</strong> separate from <strong>Python translation environment updates</strong>. The current release installs packages <strong>in the existing conda/uv environment</strong>. It no longer creates staging or backup environments.</p><div class="tip custom-block"><p class="custom-block-title">Current update flow</p><ul><li>Existing environments: install with <code>pip</code> / <code>uv pip</code> inside <code>zotero-pdf2zh-next-venv</code>.</li><li>Windows Conda first looks for <code>&lt;env&gt;\\\\python.exe</code>, then asks conda itself via <code>conda run -n ... python</code>.</li><li>Leftover <code>*-staging</code> / <code>*-backup</code> environments are removed during update. Translation uses only the canonical environment.</li><li>Managed runtimes do not inherit system <code>PYTHONPATH</code> / <code>PYTHONHOME</code>; proxy, CUDA, PATH, and other unrelated settings are preserved.</li><li>If a critical native dependency such as <code>pydantic_core</code> is damaged or resolves from global Python, the updater reinstalls the complete dependency set instead of running a mixed environment.</li></ul></div><h2 id="new-users" tabindex="-1">New users <a class="header-anchor" href="#new-users" aria-label="Permalink to “New users”">​</a></h2><p>New users do not need to choose BabelDOC, PyMuPDF, or a specific <code>pdf2zh_next</code> version manually.</p><p>On first actual use of <code>pdf2zh_next</code>, the Server:</p><ol><li>keeps an existing uv/conda environment, or creates the canonical one (uv preferred for a fresh install);</li><li>probes PyPI, USTC, TUNA, Aliyun, and an optional custom index;</li><li>installs <code>pdf2zh_next &gt;= 2.9.0,&lt;3.0.0</code> and its dependencies in that environment;</li><li>validates dependency completeness and the CLI entry point;</li><li>verifies DeepSeek V4 capability from the installed distribution without launching <code>pdf2zh_next --help</code>.</li></ol><p>The upper bound is intentional. If upstream later releases <code>pdf2zh_next 3.x</code>, a later Zotero PDF2zh release must validate and widen the supported range.</p><p>The Server itself can still start if installation fails. Retry later with <code>python update_packages.py</code>.</p><h2 id="existing-users" tabindex="-1">Existing users <a class="header-anchor" href="#existing-users" aria-label="Permalink to “Existing users”">​</a></h2><p>When an existing <code>pdf2zh_next</code> environment is detected, the current Server version asks once:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Existing Python translation environment detected</span></span>
<span class="line"><span>Current pdf2zh_next: ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Y] Check and update (recommended)</span></span>
<span class="line"><span>[N] Keep current environment</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Choose [Y/n]:</span></span></code></pre></div><p>Pressing Enter selects <code>Y</code>. The update installs into the current environment. If <code>pdf2zh_next</code> is already <strong>2.9.0 or newer</strong>, the startup prompt is skipped.</p><p>If the user selects <code>N</code>, the same Server version does not repeatedly ask. Retry later with:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update_packages.py</span></span></code></pre></div><h2 id="one-command-manual-update" tabindex="-1">One-command manual update <a class="header-anchor" href="#one-command-manual-update" aria-label="Permalink to “One-command manual update”">​</a></h2><p>From the <code>server</code> directory:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update_packages.py</span></span></code></pre></div><p>This is the only maintenance command normal users need. It keeps an existing uv or conda environment; a fresh install prefers uv. BabelDOC is a dependency of <code>pdf2zh_next</code> and does not need a separate version pin.</p><p>The flow is:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find or create the canonical environment</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>network + dependency checks</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>install in the current environment</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>validate CLI / critical native dependencies</span></span></code></pre></div><p>The same command also repairs an existing damaged environment. Global Python paths are isolated first; a failed critical import triggers one complete reinstall. Healthy environments are not reinstalled.</p><h3 id="custom-index-or-timeout" tabindex="-1">Custom index or timeout <a class="header-anchor" href="#custom-index-or-timeout" aria-label="Permalink to “Custom index or timeout”">​</a></h3><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update_packages.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --index-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://pypi.org/simple&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update_packages.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network-timeout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span></span></code></pre></div><p>To force one environment manager explicitly:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update_packages.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uv</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update_packages.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> conda</span></span></code></pre></div><h2 id="advanced-diagnostics" tabindex="-1">Advanced diagnostics <a class="header-anchor" href="#advanced-diagnostics" aria-label="Permalink to “Advanced diagnostics”">​</a></h2><h3 id="check-package-download-connectivity" tabindex="-1">Check package-download connectivity <a class="header-anchor" href="#check-package-download-connectivity" aria-label="Permalink to “Check package-download connectivity”">​</a></h3><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage_packages.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span></span></code></pre></div><p>This is read-only. It probes official PyPI, USTC, TUNA, and Aliyun and reads a small prefix of a real distribution artifact rather than only testing a mirror homepage.</p><h3 id="inspect-installed-versions" tabindex="-1">Inspect installed versions <a class="header-anchor" href="#inspect-installed-versions" aria-label="Permalink to “Inspect installed versions”">​</a></h3><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage_packages.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><h3 id="diagnose-the-translation-environment-read-only" tabindex="-1">Diagnose the translation environment (read-only) <a class="header-anchor" href="#diagnose-the-translation-environment-read-only" aria-label="Permalink to “Diagnose the translation environment (read-only)”">​</a></h3><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage_packages.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>This command does not install packages, change the environment, or call a model API. It reports the Server version, discovered uv/conda Python interpreters (both when auto mode finds two environments), installed dependency versions (including bitstring), and whether <code>bitstring.BitStream</code> can be imported and constructed. Check the Server version before running <code>python update_packages.py</code> to repair an incompatible environment. Review local file paths before sharing diagnostic output.</p><h3 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to “Update”">​</a></h3><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage_packages.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>Same as <code>python update_packages.py</code>: install into the current environment.</p><h2 id="what-latest-means" tabindex="-1">What “latest” means <a class="header-anchor" href="#what-latest-means" aria-label="Permalink to “What “latest” means”">​</a></h2><p>The updater never uses <code>--no-deps</code> to bypass upstream dependency constraints.</p><p>“Update” therefore means:</p><blockquote><p><strong>install the newest compatible combination allowed by both the Zotero PDF2zh supported range and current upstream dependency metadata.</strong></p></blockquote><p>For v4.1.0, the managed <code>pdf2zh_next</code> range is <code>&gt;=2.9.0,&lt;3.0.0</code>. It does not guarantee that every individual BabelDOC or PyMuPDF package reaches its independently newest release if that combination is not allowed by the upstream dependency graph.</p><h2 id="deepseek-v4-thinking-controls" tabindex="-1">DeepSeek V4 thinking controls <a class="header-anchor" href="#deepseek-v4-thinking-controls" aria-label="Permalink to “DeepSeek V4 thinking controls”">​</a></h2><p>Explicit DeepSeek V4 controls require the actual <code>pdf2zh_next</code> runtime to support the settings that map to:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>--deepseek-thinking-mode</span></span>
<span class="line"><span>--deepseek-reasoning-effort</span></span></code></pre></div><p>v4.1.0 requires <code>pdf2zh_next &gt;=2.9.0,&lt;3.0.0</code> for new environments. Capability detection reads the installed distribution&#39;s settings/CLI source statically instead of starting the heavyweight <code>pdf2zh_next --help</code> path.</p><p>Existing users who decline the environment update can continue using capabilities supported by their old environment. DeepSeek V4 <strong>defaults to no thinking</strong>, so an older runtime is still allowed to translate. The Server only requires <code>pdf2zh_next &gt;= 2.9.0</code> when the user explicitly enables thinking; otherwise it blocks that request before any API call so the setting cannot be silently ignored.</p><h2 id="configuration-migration" tabindex="-1">Configuration migration <a class="header-anchor" href="#configuration-migration" aria-label="Permalink to “Configuration migration”">​</a></h2><p>v4.1.0 no longer overwrites existing <code>config.json</code>, <code>config.toml</code>, or <code>venv.json</code> from their <code>.example</code> templates on every startup.</p><p>During migration it:</p><ul><li>preserves existing user values;</li><li>preserves unknown custom keys and translators;</li><li>adds missing defaults for normal configuration fields;</li><li>refreshes release-managed package constraints in <code>venv.json</code> while preserving additional third-party packages added by the user;</li><li>backs up an unparseable old config as <code>.invalid.bak</code> before restoring defaults.</li></ul><h2 id="special-pdf-parser-failures" tabindex="-1">Special PDF parser failures <a class="header-anchor" href="#special-pdf-parser-failures" aria-label="Permalink to “Special PDF parser failures”">​</a></h2><p>Some malformed PDFs can still trigger BabelDOC/PyMuPDF parser errors such as:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cannot parse object</span></span>
<span class="line"><span>Expected dict-like object, got NoneType</span></span></code></pre></div><p>Zotero PDF2zh does not automatically rewrite, repack, or rasterize every user PDF. For isolated failures, re-download the original PDF first and only repair the affected file if necessary.</p><h2 id="server-source-updates" tabindex="-1">Server source updates <a class="header-anchor" href="#server-source-updates" aria-label="Permalink to “Server source updates”">​</a></h2><p>Server source updates remain separate:</p><div class="language-shell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update_source=github</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update_source=gitee</span></span></code></pre></div><p>Both GitHub and Gitee are tried for version checks and <code>server.zip</code> downloads. <code>--update_source</code> only chooses <strong>which source is tried first</strong>; if it fails or is older, the other source is used. The unpacked Server version is still verified.</p><p>Gitee Release attachments may show a security captcha or 404, so the updater also tries Gitee <code>raw/vX.Y.Z/server.zip</code>, GitHub Releases, and the versioned file in the GitHub repo. Do not use Gitee source archives (<code>repository/archive/*.zip</code>); that endpoint often returns HTML.</p><p>Manual download:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://github.com/guaguastandup/zotero-pdf2zh/releases/latest/download/server.zip</span></span>
<span class="line"><span>https://gitee.com/guaguastandup/zotero-pdf2zh/raw/v4.1.1/server.zip</span></span></code></pre></div><p>Source updates and Python translation-environment updates remain independent operations.</p><h2 id="project-notices" tabindex="-1">Project notices <a class="header-anchor" href="#project-notices" aria-label="Permalink to “Project notices”">​</a></h2><p>On startup the Server fetches <code>server/notice.json</code> from <code>main</code>. <code>community</code> (QQ groups, join answer, docs) is always shown; <code>notices</code> are filtered by the local version. Fetch failures are ignored and never block startup.</p><p>To change the QQ group number, retire an announcement, or warn that a version cannot auto-update, edit that file on <code>main</code>. No new Server release is required.</p><p>Empty <code>affects</code> or <code>*</code> shows the notice to every version. Set <code>enabled</code> to <code>false</code> to retire a notice. Groups with <code>status: full</code> are not printed.</p>`,68)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};